import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
// START Google Fonts Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
// END Google Fonts Loader



export type LineGraphProps = Record<string, any>;

const LineGraph: React.FC<LineGraphProps> = ({
  backgroundColor = "#050505",
  primaryColor = "#ffed3d",
  textColor = "#ffffff",
  transparentBackground = false,
  titleText = "4x Revenue",
  durationInSeconds = 5,
  numberOfPoints = 8,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const totalDurationInFrames = durationInSeconds * fps;

  // Safety for transparency
  const bgStyle = transparentBackground ? "transparent" : backgroundColor;

  // Generate stable data points representing an upward trend
  const dataPoints = useMemo(() => {
    const points = [];
    let currentY = 20; // Start low (visual percentage from bottom)
    const stepX = 100 / (numberOfPoints - 1);

    for (let i = 0; i < numberOfPoints; i++) {
      // Create a generally upward trend with some random variance
      // Using a deterministic "random" based on index to keep it stable across renders
      const noise = Math.sin(i * 123.45) * 10;
      const upwardPush = (i / numberOfPoints) * 70; // Grow up to 70% higher

      let y = currentY + upwardPush + noise;
      // Clamp Y to keep it within reasonable graph bounds (10% to 90% height)
      y = Math.max(10, Math.min(90, y));

      points.push({
        x: i * stepX,
        y: y,
        value: Math.round(y * 100), // Mock value for labels
      });
    }
    return points;
  }, [numberOfPoints]);

  // Animation Progress
  // We want the graph to draw over roughly 60-70% of the duration
  const graphAnimationDuration = durationInSeconds * fps * 0.7;
  
  // Controls the "cursor" of the drawing (0 to numberOfPoints - 1)
  const progress = spring({
    frame: frame - 15, // Delay slightly for title
    fps,
    config: {
      damping: 15,
      stiffness: 80,
    },
    durationInFrames: graphAnimationDuration,
  });

  // Map spring progress to total index range
  const currentProgressIndex = interpolate(
    progress,
    [0, 1],
    [0, numberOfPoints - 1]
  );

  // Title Animation
  const titleOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateRight: "clamp",
  });
  const titleOffset = interpolate(frame, [0, 20], [20, 0], {
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });

  // Global Animations (Zoom & Blur)
  const zoomScale = interpolate(frame, [0, totalDurationInFrames], [1.05, 1], {
    extrapolateRight: "clamp",
  });
  
  const blurRadius = interpolate(frame, [0, 25], [10, 0], {
    extrapolateRight: "clamp",
  });

  // Layout Constants - Increased padding for "floating" look
  const graphPadding = { top: 250, right: 150, bottom: 250, left: 150 };
  const graphWidth = width - graphPadding.left - graphPadding.right;
  const graphHeight = height - graphPadding.top - graphPadding.bottom;

  // Helper to convert data coordinates (0-100) to pixel coordinates
  const toPixels = (xPerc: number, yPerc: number) => {
    return {
      x: graphPadding.left + (xPerc / 100) * graphWidth,
      y: height - graphPadding.bottom - (yPerc / 100) * graphHeight,
    };
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgStyle,
        fontFamily: "Inter, sans-serif",
        color: textColor,
        transform: `scale(${zoomScale})`,
        filter: `blur(${blurRadius}px)`,
        transformOrigin: "center center",
      }}
    >
      {/* Header */}
      <div
        style={{
          position: "absolute",
          top: 60,
          left: 100,
          opacity: titleOpacity,
          transform: `translateY(${titleOffset}px)`,
        }}
      >
        <h1
          style={{
            margin: 0,
            fontSize: 80,
            fontWeight: 700,
            color: textColor,
            letterSpacing: "-0.02em",
          }}
        >
          {titleText}
        </h1>
      </div>

      {/* Graph Area */}
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", top: 0, left: 0 }}
      >
        <defs>
          <linearGradient id="lineGradient" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={primaryColor} stopOpacity="0.5" />
            <stop offset="100%" stopColor={primaryColor} stopOpacity="0" />
          </linearGradient>
        </defs>

        {/* Grid Lines & Percentages Removed for floating effect */}

        {/* Line Segments & Fill */}
        {dataPoints.map((point, index) => {
          if (index === dataPoints.length - 1) return null;

          const nextPoint = dataPoints[index + 1];
          const start = toPixels(point.x, point.y);
          const end = toPixels(nextPoint.x, nextPoint.y);

          // Calculate visibility of this specific segment
          // Segment index corresponds to 'index'.
          // If currentProgressIndex is 0.5, we are halfway through segment 0.
          // If currentProgressIndex is 1.5, segment 0 is done, halfway through segment 1.
          
          const segmentProgress = interpolate(
            currentProgressIndex,
            [index, index + 1],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          if (segmentProgress <= 0) return null;

          // Interpolate end position based on progress
          const currentEndX = interpolate(segmentProgress, [0, 1], [start.x, end.x]);
          const currentEndY = interpolate(segmentProgress, [0, 1], [start.y, end.y]);

          // Area Fill (Polygon)
          // Construct points: Start -> CurrentEnd -> BottomRight -> BottomLeft
          const bottomY = height - graphPadding.bottom;
          const pointsString = `
            ${start.x},${start.y} 
            ${currentEndX},${currentEndY} 
            ${currentEndX},${bottomY} 
            ${start.x},${bottomY}
          `;

          return (
            <g key={`segment-${index}`}>
              {/* Fill under the line */}
              <polygon
                points={pointsString}
                fill="url(#lineGradient)"
                opacity={0.3}
              />
              {/* The Line Segment */}
              <line
                x1={start.x}
                y1={start.y}
                x2={currentEndX}
                y2={currentEndY}
                stroke={primaryColor}
                strokeWidth={6}
                strokeLinecap="round"
              />
            </g>
          );
        })}

        {/* Points (Dots) */}
        {dataPoints.map((point, index) => {
          const pos = toPixels(point.x, point.y);
          
          // Animate scale based on when the line reaches this point
          // The line reaches point 'index' when currentProgressIndex passes 'index'
          // Exception: Point 0 appears immediately or quickly
          
          const triggerIndex = Math.max(0, index - 0.1); // Slightly before the line fully arrives for smoother feel
          
          // Simpler approach using the interpolated progress value directly
          const progressDiff = currentProgressIndex - index;
          const dotScale = interpolate(
            progressDiff,
            [-0.2, 0, 0.5],
            [0, 1.2, 1], // Pop effect
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );
          
          return (
            <g
                key={`point-${index}`}
                transform={`translate(${pos.x}, ${pos.y}) scale(${dotScale})`}
            >
              <circle
                r={10}
                fill={backgroundColor}
                stroke={primaryColor}
                strokeWidth={4}
              />
            </g>
          );
        })}
      </svg>
    </AbsoluteFill>
  );
};

export default LineGraph;